customTools.func:
const phone = typeof $phone_number !== 'undefined' ? String($phone_number).trim() : '';
const text = typeof $message !== 'undefined' ? String($message).trim() : '';

if (!phone || !text) {
    return "Error: Both phone_number and message are required.";
}

try {
    const axios = require('axios');
    const serverUrl = 'https://milk-rebound-bedding-src.trycloudflare.com';

    const response = await axios.post(`${serverUrl}/api/send`, {
        to: phone,
        text: text
    }, {
        headers: { 'Content-Type': 'application/json' }
    });

    return `WhatsApp message sent successfully to ${phone}! Status: ${response.status}`;
} catch (error) {
    return `WhatsApp tool error: ${error.response ? JSON.stringify(error.response.data) : error.message}`;
}
